function blankDesign(){return {schemaVersion:1,designId:uid(),name:'Untitled design',description:'',deviceProfileId:'esp32-c3-gc9a01-240',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),canvas:{width:240,height:240,shape:'circle',backgroundColor:'#080b10',clipToShape:true},objects:[]}}
