function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)}
function historySnapshot(){const d=clone(state.design);delete d.updatedAt;return JSON.stringify(d)}
function saveDraft(){if(!state.design)return;const before=state.lastSnapshot,after=historySnapshot();if(before&&before!==after&&!state.historyLock){state.history.push(before);if(state.history.length>50)state.history.shift();state.future=[]}state.design.updatedAt=new Date().toISOString();state.lastSnapshot=historySnapshot();if(localStorage.getItem(AUTOSAVE_KEY)!=='false')localStorage.setItem(DRAFT_KEY,JSON.stringify(state.design));}
function restoreHistory(snapshot){state.historyLock=true;state.design=JSON.parse(snapshot);state.selected=state.design.objects.find(o=>o.id===state.selected)?.id||state.design.objects[0]?.id||null;state.lastSnapshot=historySnapshot();state.design.updatedAt=new Date().toISOString();if(localStorage.getItem(AUTOSAVE_KEY)!=='false')localStorage.setItem(DRAFT_KEY,JSON.stringify(state.design));state.historyLock=false;render()}
function undoDesign(){if(!state.history.length)return;state.future.push(historySnapshot());restoreHistory(state.history.pop())}
function redoDesign(){if(!state.future.length)return;state.history.push(historySnapshot());restoreHistory(state.future.pop())}
function getDesigns(){try{const value=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');return Array.isArray(value)?value.filter(d=>d&&typeof d==='object'&&!Array.isArray(d)&&typeof d.designId==='string'&&typeof d.name==='string'&&d.canvas&&typeof d.canvas==='object'&&Array.isArray(d.objects)):[]}catch{return []}}
function persistDesign(){if(!state.design)return;saveDraft();const list=getDesigns().filter(d=>d.designId!==state.design.designId);list.unshift(clone(state.design));localStorage.setItem(STORAGE_KEY,JSON.stringify(list));toast('Design saved on this device');}
function loadDesign(d){state.design=clone(d);state.selected=d.objects[0]?.id||null;state.history=[];state.future=[];state.lastSnapshot=historySnapshot();state.view='editor';showView('editor');saveDraft()}
function addObject(type){const labels={text:'Text',image:'Image',shape:'Shape','digital-clock':'Digital time',date:'Date',weather:'Weather',moon:'Moon phase','sunrise-sunset':'Sunrise / sunset',gauge:'Gauge','progress-ring':'Progress ring','analog-clock':'Analog clock'};const o={id:uid(),type,name:labels[type]||'Object',visible:true,locked:false,transform:{x:55,y:85,width:130,height:40,anchor:'top-left',zIndex:state.design.objects.length},style:{}};if(type==='digital-clock'){o.clockMode='digital';o.timeFormat='24h';o.dataBinding={source:'time',format:'HH:mm'};o.textStyle={fontSize:34,fontWeight:600,fill:'#ffffff'}}else if(type==='date'){o.dataBinding={source:'date',format:'ddd, DD MMM'};o.textStyle={fontSize:12,fill:'#c5cfdd'}}else if(type==='weather'){o.dataBinding={source:'temperature'};o.weatherFields=['temperature','condition'];o.textStyle={fontSize:25,fill:'#b7f36b'}}else if(type==='image'){o.assetId='';o.name='Image';}else if(type==='text'){o.text='YOUR TEXT';o.textStyle={fontSize:16,fill:'#ffffff'}}else if(type==='analog-clock'){o.clockMode='analog';o.handConfig={hour:{},minute:{},second:{}}}else if(type==='shape'){o.shape='circle';o.style={fill:'#b7f36b'}}else if(type==='moon'){o.dataBinding={source:'moonrise'};o.text='☾';o.textStyle={fontSize:30,fill:'#fff'}}else if(type==='sunrise-sunset'){o.dataBinding={source:'sunrise'};o.text='☀  05:48 · 17:42';o.textStyle={fontSize:12,fill:'#ffd58b'}}else{o.text='';o.textStyle={fontSize:16,fill:'#fff'}}state.design.objects.push(o);state.selected=o.id;saveDraft();render()}
function roundFirmwarePixel(value){const number=Number(value);if(!Number.isFinite(number))return 0;return number<0?-Math.floor(-number+0.5):Math.floor(number+0.5)}
function selectedObject(){return state.design?.objects.find(o=>o.id===state.selected)}
function objectText(o){const now=new Date(),pad=n=>String(n).padStart(2,'0');if(o.type==='digital-clock'){let hour=now.getHours();if(o.timeFormat==='12h')hour=hour%12||12;const fmt=o.dataBinding?.format||'HH:mm';let value=fmt.replace(/HH/g,pad(hour)).replace(/mm/g,pad(now.getMinutes())).replace(/ss/g,pad(now.getSeconds()));if(o.showSeconds&&!fmt.includes('ss'))value+=':'+pad(now.getSeconds());if(o.timeFormat==='12h')value+=now.getHours()>=12?' PM':' AM';return value}if(o.type==='date'){const weekdays=['SUN','MON','TUE','WED','THU','FRI','SAT'],months=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'],fmt=o.dataBinding?.format||'ddd, DD MMM';return fmt.replace(/YYYY|ddd|MMM|MM|DD/g,token=>token==='YYYY'?String(now.getFullYear()):token==='ddd'?weekdays[now.getDay()]:token==='MMM'?months[now.getMonth()]:token==='MM'?pad(now.getMonth()+1):pad(now.getDate()))}if(o.type==='weather')return '27 C';if(o.type==='analog-clock')return '◷';if(o.type==='image')return '';if(o.type==='text')return o.text??'';return o.text||o.name}
// TFT_eSPI GLCD Font 1 (Adafruit_GFX 5x7), all 256 byte glyphs.
// Column bytes and 6x8 cells mirror the firmware's TFT_eSprite rasterizer.
const TFT_FONT1_GLYPHS='';
function setPreviewText(element,text,style){
 const value=String(text??''),codes=[...new TextEncoder().encode(value)],fontSize=Number(style.fontSize)||16,scaleX=(fontSize/8)*(Number(style.scaleX)||1),scaleY=(fontSize/8)*(Number(style.scaleY)||1),spacing=Number(style.letterSpacing)||0;
 const advance=6*scaleX+spacing,textWidth=Math.max(0,codes.length*advance-spacing),glyphHeight=8*scaleY;
 const clip=document.createElement('span');clip.className='glyph-preview';Object.assign(clip.style,{display:'flex',alignItems:'center',justifyContent:style.textAlign==='left'?'flex-start':style.textAlign==='right'?'flex-end':'center',width:'100%',height:'100%',overflow:'hidden',whiteSpace:'pre'});
 const bitmap=document.createElement('canvas');bitmap.width=Math.max(1,Math.ceil(textWidth));bitmap.height=Math.max(1,Math.ceil(glyphHeight));bitmap.style.width=(textWidth/240*100)+'cqw';bitmap.style.height=(glyphHeight/240*100)+'cqw';bitmap.style.imageRendering='pixelated';bitmap.style.flex='0 0 auto';
 const ctx=bitmap.getContext('2d');if(ctx){ctx.imageSmoothingEnabled=false;ctx.fillStyle=style.fill||'#ffffff';const bold=Number(style.fontWeight)>=600;
  let cursorX=0;
  for(let index=0;index<codes.length;index++){let code=codes[index];if(code>175)code++;if(code>255)continue;const offset=code*10;
   for(let row=0;row<8;row++){let runStart=-1;
    for(let column=0;column<=6;column++){const pixelOn=column<5&&(parseInt(TFT_FONT1_GLYPHS.slice(offset+column*2,offset+column*2+2),16)&(1<<row))!==0;
     if(pixelOn&&runStart<0)runStart=column;
     else if(!pixelOn&&runStart>=0){const left=Math.floor(cursorX+runStart*scaleX),right=Math.ceil(cursorX+column*scaleX),top=Math.floor(row*scaleY),bottom=Math.ceil((row+1)*scaleY);
      if(right>left&&bottom>top){ctx.fillRect(left,top,right-left,bottom-top);if(bold&&left+1<bitmap.width)ctx.fillRect(left+1,top,Math.min(right-left,bitmap.width-left-1),bottom-top)}
      runStart=-1;
     }
    }
   }
   cursorX+=advance;
  }
 }
 clip.append(bitmap);element.append(clip)
}
function renderWeatherPreview(element,object,style){
 const fields=Array.isArray(object.weatherFields)?object.weatherFields:['temperature'];
 const showTemperature=fields.length===0||fields.includes('temperature'),showCondition=fields.includes('condition');
 if(showTemperature&&showCondition){
  element.style.position='relative';element.style.display='block';
  const top=document.createElement('div');Object.assign(top.style,{position:'absolute',left:'0',top:'0',width:'100%',height:'58%',display:'flex',alignItems:'center',justifyContent:'center',overflow:'hidden'});
  const bottom=document.createElement('div');Object.assign(bottom.style,{position:'absolute',left:'0',top:'48%',width:'100%',height:'52%',display:'flex',alignItems:'center',justifyContent:'center',overflow:'hidden'});
  const conditionStyle={...style,fontSize:(Number(style.fontSize)||16)>12?(Number(style.fontSize)||16)/2:8};
  setPreviewText(top,'27 C',style);setPreviewText(bottom,'Cloudy',conditionStyle);element.append(top);element.append(bottom);return;
 }
 setPreviewText(element,showCondition?'Cloudy':'27 C',style);
}
function renderAnalogClockPreview(element,object,now=new Date()){
 const width=Math.max(1,roundFirmwarePixel(object?.transform?.width??100)),height=Math.max(1,roundFirmwarePixel(object?.transform?.height??100));
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
 svg.setAttribute('viewBox','0 0 '+width+' '+height);svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('preserveAspectRatio','xMidYMid meet');
 const cx=width/2,cy=height/2,radius=Math.min(width,height)/2-2;
 if(radius<8){element.append(svg);return}
 const add=(tag,attrs)=>{const node=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [key,value] of Object.entries(attrs))node.setAttribute(key,String(value));svg.append(node);return node};
 const point=(degrees,r)=>{const angle=degrees*Math.PI/180;return{x:cx+Math.cos(angle)*r,y:cy+Math.sin(angle)*r}};
 add('circle',{cx,cy,r:radius,fill:'none',stroke:'currentColor','stroke-width':1});
 for(let tick=0;tick<12;tick++){
  const angle=tick*30-90,outer=point(angle,radius-2),inner=point(angle,radius-(tick%3===0?9:5));
  add('line',{x1:inner.x,y1:inner.y,x2:outer.x,y2:outer.y,stroke:'currentColor','stroke-width':1});
 }
 const seconds=now.getSeconds(),minutes=now.getMinutes()+seconds/60,hours=(now.getHours()%12)+minutes/60;
 const hands=[{angle:hours*30-90,r:radius*.48,color:'currentColor'},{angle:minutes*6-90,r:radius*.72,color:'currentColor'},{angle:seconds*6-90,r:radius*.86,color:'#ff0000'}];
 for(const hand of hands){const end=point(hand.angle,hand.r);add('line',{x1:cx,y1:cy,x2:end.x,y2:end.y,stroke:hand.color,'stroke-width':1})}
 add('circle',{cx,cy,r:3,fill:'currentColor'});
 element.append(svg);
}
function renderShapePreview(element,object,style){
 const width=Math.max(1,roundFirmwarePixel(object.transform.width)),height=Math.max(1,roundFirmwarePixel(object.transform.height));
 const shape=object.shape||'rect',fill=style.fill||'#ffffff',hasStroke=Number(style.strokeWidth??0)>0;
 const stroke=hasStroke?(style.stroke||'#000000'):'none';
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
 svg.setAttribute('viewBox','0 0 '+width+' '+height);
 svg.setAttribute('width','100%');svg.setAttribute('height','100%');
 svg.setAttribute('preserveAspectRatio','none');
 svg.style.display='block';
 let primitive;
 if(shape==='circle'){
  primitive=document.createElementNS('http://www.w3.org/2000/svg','circle');
  primitive.setAttribute('cx',String(width/2));primitive.setAttribute('cy',String(height/2));
  primitive.setAttribute('r',String(Math.min(width,height)/2));
 }else if(shape==='line'){
  primitive=document.createElementNS('http://www.w3.org/2000/svg','line');
  primitive.setAttribute('x1','0');primitive.setAttribute('y1','0');
  primitive.setAttribute('x2',String(width));primitive.setAttribute('y2',String(height));
  primitive.setAttribute('stroke',hasStroke?(style.stroke||fill):fill);
  primitive.setAttribute('stroke-width','1');
  svg.append(primitive);element.style.background='transparent';element.style.border='none';element.style.borderRadius='0';element.append(svg);return;
 }else{
  primitive=document.createElementNS('http://www.w3.org/2000/svg','rect');
  primitive.setAttribute('x','0');primitive.setAttribute('y','0');
  primitive.setAttribute('width',String(width));primitive.setAttribute('height',String(height));
  if(shape==='rounded-rect')primitive.setAttribute('rx',String(Math.max(0,Number(style.cornerRadius)||0)));
 }
 primitive.setAttribute('fill',fill);primitive.setAttribute('stroke',stroke);
 if(hasStroke)primitive.setAttribute('stroke-width','1');
 svg.append(primitive);element.style.background='transparent';element.style.border='none';element.style.borderRadius='0';element.append(svg);
}
function renderSelectionOverlay(canvas){
 const stage=canvas.closest('.canvas-stage');if(!stage)return;
 const selected=state.design.objects.find(o=>o.id===state.selected&&o.visible!==false);
 const previous=stage.querySelector('.selected-object-overlay');if(previous)previous.remove();
 if(!selected)return;
 const canvasRect=canvas.getBoundingClientRect(),stageRect=stage.getBoundingClientRect();
 const borderLeft=parseFloat(getComputedStyle(canvas).borderLeftWidth)||0;
 const borderTop=parseFloat(getComputedStyle(canvas).borderTopWidth)||0;
 const scaleX=canvas.clientWidth/240,scaleY=canvas.clientHeight/240,t=selected.transform;
 const overlay=document.createElement('div');overlay.className='selected-object-overlay';
 Object.assign(overlay.style,{
  left:(canvasRect.left-stageRect.left+borderLeft+t.x*scaleX)+'px',
  top:(canvasRect.top-stageRect.top+borderTop+t.y*scaleY)+'px',
  width:(t.width*scaleX)+'px',height:(t.height*scaleY)+'px',
  transform:'rotate('+(t.rotation||0)+'deg)'
 });
 if(!selected.locked){
  ['nw','ne','sw','se'].forEach(corner=>{
   const handle=document.createElement('span');handle.className='resize-handle '+corner;
   handle.setAttribute('aria-label','Resize '+selected.name);
   handle.addEventListener('pointerdown',ev=>startResize(ev,selected.id,corner));
   overlay.append(handle);
  });
 }
 stage.append(overlay);
}
function renderCanvas(){const c=$('#watchCanvas');if(!c)return;c.style.background=state.design.canvas.backgroundColor;c.innerHTML='';state.design.objects.filter(o=>o.visible!==false).sort((a,b)=>(a.transform.zIndex||0)-(b.transform.zIndex||0)).forEach(o=>{const el=document.createElement('div');el.className='watch-object'+(o.locked?' locked':'');el.dataset.id=o.id;const t=o.transform,s=o.textStyle||{},st=o.style||{};Object.assign(el.style,{left:(roundFirmwarePixel(t.x)/240*100)+'%',top:(roundFirmwarePixel(t.y)/240*100)+'%',width:(roundFirmwarePixel(t.width)/240*100)+'%',height:(roundFirmwarePixel(t.height)/240*100)+'%',zIndex:t.zIndex??0,opacity:t.opacity??1,transform:'rotate('+(t.rotation||0)+'deg)',color:s.fill||st.fill||'#fff',fontSize:((s.fontSize||16)/240*100)+'cqw',fontWeight:s.fontWeight||400,fontFamily:s.fontFamily||'inherit',letterSpacing:(s.letterSpacing||0)+'px',background:s.backgroundColor||st.backgroundColor||'transparent',borderRadius:(st.cornerRadius||0)+'px',border:st.stroke?((st.strokeWidth||1)+'px solid '+st.stroke):'none',textAlign:s.textAlign||'center'});if(o.type==='shape'){renderShapePreview(el,o,st)}else if(o.type==='image'){const img=state.images.find(a=>a.id===o.assetId);if(img){const im=document.createElement('img');im.src=img.data;el.append(im)}else el.textContent='＋ Image'}else if(o.type==='weather'){renderWeatherPreview(el,o,s)}else if(o.type==='analog-clock'){renderAnalogClockPreview(el,o)}else setPreviewText(el,objectText(o),s);el.addEventListener('pointerdown',e=>startDrag(e,o.id));el.addEventListener('click',e=>{e.stopPropagation();state.selected=o.id;render()});c.append(el)});renderSelectionOverlay(c);$('#canvasSize').textContent=state.design.canvas.width+' × '+state.design.canvas.height;$('#canvasSizeFooter').textContent=state.design.canvas.width+' × '+state.design.canvas.height;$('#canvasName').textContent=state.design.name;$('#layerCount').textContent=state.design.objects.length}
function startDrag(e,id){const o=state.design.objects.find(x=>x.id===id);if(!o||o.locked)return;e.preventDefault();state.selected=id;const canvas=$('#watchCanvas');state.drag={id,startX:e.clientX,startY:e.clientY,x:o.transform.x,y:o.transform.y,scaleX:240/Math.max(1,canvas.clientWidth),scaleY:240/Math.max(1,canvas.clientHeight)};e.currentTarget.setPointerCapture(e.pointerId);const move=ev=>{if(!state.drag)return;const d=state.drag;o.transform.x=Math.max(-100,Math.min(240,d.x+(ev.clientX-d.startX)*d.scaleX));o.transform.y=Math.max(-100,Math.min(240,d.y+(ev.clientY-d.startY)*d.scaleY));renderCanvas();};const end=()=>{state.drag=null;saveDraft();window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end)}
function startResize(e,id,corner){e.preventDefault();e.stopPropagation();const o=state.design.objects.find(x=>x.id===id);if(!o||o.locked)return;const canvas=$('#watchCanvas'),scaleX=240/Math.max(1,canvas.clientWidth),scaleY=240/Math.max(1,canvas.clientHeight),t=o.transform,textTypes=['text','digital-clock','date','weather','moon','sunrise-sunset'],textStyle=o.textStyle||(textTypes.includes(o.type)?(o.textStyle={fontSize:16,fill:'#ffffff'}):null);const start={x:e.clientX,y:e.clientY,left:t.x,top:t.y,width:t.width,height:t.height,glyphScaleX:Number(textStyle?.scaleX??1),glyphScaleY:Number(textStyle?.scaleY??1)};const move=ev=>{const dx=(ev.clientX-start.x)*scaleX,dy=(ev.clientY-start.y)*scaleY;let left=start.left,top=start.top,width=start.width,height=start.height;if(corner.includes('e'))width=Math.max(4,start.width+dx);if(corner.includes('s'))height=Math.max(4,start.height+dy);if(corner.includes('w')){width=Math.max(4,start.width-dx);left=start.left+(start.width-width)}if(corner.includes('n')){height=Math.max(4,start.height-dy);top=start.top+(start.height-height)}Object.assign(t,{x:left,y:top,width,height});if(textStyle){if(corner.includes('e')||corner.includes('w'))textStyle.scaleX=Math.max(.1,Math.min(8,start.glyphScaleX*(width/start.width)));if(corner.includes('n')||corner.includes('s'))textStyle.scaleY=Math.max(.1,Math.min(8,start.glyphScaleY*(height/start.height)))}renderCanvas()};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);saveDraft();render()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end)}
