function download(name,data,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function exportJSON(){try{await ensureSchemaLoaded();const errors=validateDesign(state.design);if(errors.length){toast('Fix '+errors.length+' design issue(s) before export');return}const assetIds=[...new Set(state.design.objects.filter(o=>o.type==='image').map(o=>o.assetId))];const assets=assetIds.map(id=>state.images.find(a=>a.id===id));if(assets.some(a=>!a))throw Error('One or more image layers have missing source assets');const project={format:'watch-face-studio-project',version:1,design:clone(state.design),assets:assets.map(a=>({id:a.id,name:a.name,data:a.data}))};if(assets.reduce((total,a)=>total+a.data.length,0)>8000000)throw Error('Bundled image data exceeds the 8 MB portable project limit');const projectSchema=await ensureProjectSchemaLoaded();const projectErrors=validateJsonSchema(projectSchema,project);if(projectErrors.length)throw Error(projectErrors[0]);download((state.design.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'watch-face')+'.wfsproject.json',JSON.stringify(project,null,2),'application/json');toast('Portable project exported with '+assets.length+' image asset(s)')}catch(e){toast('Export blocked: '+e.message)}}
