function validateDesign(d){if(!d||typeof d!=='object'||Array.isArray(d))return ['Design must be a JSON object'];const e=[];if(!d.name?.trim())e.push('Name is required');if(!d.canvas||d.canvas.width<1||d.canvas.height<1)e.push('Canvas dimensions are invalid');if(!Array.isArray(d.objects))e.push('Objects must be an array');else{if(d.objects.length>128)e.push('Maximum 128 objects');for(const o of d.objects){if(!o.id||!o.type||!o.transform)e.push('Every object needs id, type and transform');if(o.type==='image'&&!o.assetId)e.push('Image layer is missing an asset');if(['digital-clock','date'].includes(o.type)&&!o.dataBinding)e.push(o.name+' needs a data binding')}}if(state.schema)e.push(...validateJsonSchema(state.schema,d));return [...new Set(e)].slice(0,30)}
async function ensureSchemaLoaded(){if(state.schema)return state.schema;const res=await fetch('./shared/schemas/watch-face.schema.json');if(!res.ok)throw Error('Shared Watch Face schema is unavailable');state.schema=await res.json();return state.schema}
async function ensureProjectSchemaLoaded(){if(state.projectSchema)return state.projectSchema;const res=await fetch('./shared/schemas/watch-face-project.schema.json');if(!res.ok)throw Error('Portable project schema is unavailable');state.projectSchema=await res.json();return state.projectSchema}
 async function validateAgainstSchema(){try{const schema=await ensureSchemaLoaded();const errors=validateJsonSchema(schema,state.design);if(errors.length)toast('Schema found '+errors.length+' issue(s): '+errors[0]);else toast('Design matches shared Watch Face schema')}catch(e){toast('Schema validation unavailable: '+e.message)}}
async function saveAssets(assets){if(!assets.length)return;const db=await openAssetDB();return new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');const store=tx.objectStore('assets');assets.forEach(asset=>store.put(asset));tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||Error('Asset import transaction aborted'))}})}
function importJSON(file){if(!file)return;const input=$('#jsonInput');const resetInput=()=>{if(input)input.value=''};if(file.size>12*1024*1024){toast('Import file exceeds the 12 MB safety limit');resetInput();return}const reader=new FileReader();reader.onerror=()=>{toast('Could not read the selected project file');resetInput()};reader.onabort=()=>{toast('Project import was cancelled');resetInput()};reader.onload=async()=>{try{await ensureSchemaLoaded();const parsed=JSON.parse(reader.result);let d=parsed,assets=[];if(parsed?.format==='watch-face-studio-project'){const projectSchema=await ensureProjectSchemaLoaded();const projectErrors=validateJsonSchema(projectSchema,parsed);if(projectErrors.length)throw Error(projectErrors[0]);d=parsed.design;assets=parsed.assets;const ids=new Set();for(const asset of assets){if(ids.has(asset.id))throw Error('Project contains a duplicate image asset ID');ids.add(asset.id);const existing=state.images.find(local=>local.id===asset.id);if(existing&&existing.data!==asset.data)throw Error('Project image asset ID conflicts with a different image already stored in this browser')}const required=new Set((d.objects||[]).filter(o=>o.type==='image').map(o=>o.assetId));for(const id of required)if(!ids.has(id))throw Error('Portable project is missing image asset '+id);for(const id of ids)if(!required.has(id))throw Error('Portable project contains an unused image asset '+id);if(assets.reduce((total,a)=>total+a.data.length,0)>8000000)throw Error('Bundled image data exceeds the 8 MB import limit')}const errors=validateDesign(d);if(errors.length)throw Error(errors.join('; '));const requiredIds=(d.objects||[]).filter(o=>o.type==='image').map(o=>o.assetId);const bundledIds=new Set(assets.map(a=>a.id));for(const id of requiredIds)if(!bundledIds.has(id)&&!state.images.some(a=>a.id===id))throw Error('Image asset '+id+' is not available in this browser or project file');await saveAssets(assets);if(assets.length){const merged=new Map(state.images.map(a=>[a.id,a]));assets.forEach(a=>merged.set(a.id,a));state.images=[...merged.values()]}loadDesign(d);toast('Design imported with '+assets.length+' bundled image asset(s)')}catch(e){toast('Import failed: '+e.message)}finally{resetInput()}};reader.readAsText(file)}
function openAssetDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('watch-face-studio-assets',1);req.onupgradeneeded=()=>req.result.createObjectStore('assets',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function saveAsset(asset){const db=await openAssetDB();return new Promise((resolve,reject)=>{const tx=db.transaction('assets','readwrite');tx.objectStore('assets').put(asset);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function loadAssets(){try{const db=await openAssetDB();state.images=await new Promise((resolve,reject)=>{const req=db.transaction('assets').objectStore('assets').getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)});db.close()}catch(e){console.warn('Image asset storage unavailable',e)}}
function addImage(file){
 const input=$('#imageInput');
 const resetInput=()=>{if(input)input.value=''};
 if(!file)return;
 if(!file.type.startsWith('image/')){toast('Please select a supported image file');resetInput();return}
 if(file.size>5*1024*1024){toast('Image exceeds the 5 MB source-file limit');resetInput();return}
 const reader=new FileReader();
 reader.onerror=()=>{toast('Could not read the selected image');resetInput()};
 reader.onabort=()=>{toast('Image import was cancelled');resetInput()};
 reader.onload=async()=>{
  try{
   if(typeof reader.result!=='string'||!reader.result.startsWith('data:image/'))throw Error('The selected file did not produce a valid image');
   if(reader.result.length>8000000)throw Error('Encoded image exceeds the 8 MB portable asset limit');
   const usedIds=new Set((state.design?.objects||[]).filter(o=>o.type==='image').map(o=>o.assetId));
   if(usedIds.size>=16)throw Error('A portable project can contain at most 16 image assets');
   const existingBytes=state.images.filter(asset=>usedIds.has(asset.id)).reduce((total,asset)=>total+asset.data.length,0);
   if(existingBytes+reader.result.length>8000000)throw Error('Images in this design exceed the 8 MB portable project limit');
   const id=uid(),asset={id,data:reader.result,name:file.name};
   await saveAsset(asset);
   state.images.push(asset);
   const o={id:uid(),type:'image',name:file.name.slice(0,40),assetId:id,visible:true,locked:false,transform:{x:30,y:30,width:180,height:180,anchor:'top-left',zIndex:state.design.objects.length}};
   state.design.objects.push(o);state.selected=o.id;saveDraft();render();
   toast('Image saved in this browser and added to the design');
  }catch(e){toast('Could not add image: '+e.message)}
  finally{resetInput()}
 };
 try{reader.readAsDataURL(file)}catch(e){toast('Could not start image import: '+e.message);resetInput()}
}
async function sendLegacyCommand(command){if(!state.bleChar){toast('Connect to the watch first');return false}try{const bytes=new TextEncoder().encode(command);if(state.bleChar.properties.write&&state.bleChar.writeValueWithResponse)await state.bleChar.writeValueWithResponse(bytes);else if(state.bleChar.writeValueWithoutResponse)await state.bleChar.writeValueWithoutResponse(bytes);else await state.bleChar.writeValue(bytes);return true}catch(e){toast('BLE command failed: '+e.message);return false}}
function legacyStatus(message){const el=$('#legacyStatus');if(el)el.textContent=message}
function handleLegacyNotification(event){const chunk=new TextDecoder().decode(event.target.value);if(chunk.startsWith('AUTO_SLEEP:')){$('#autoSleepSelect').value=chunk.split(':')[1];legacyStatus('Current auto-sleep setting received');return}if(chunk.startsWith('AUTO_SLEEP_OK:')){legacyStatus('Auto-sleep setting saved');return}if(chunk==='ERR_AUTO_SLEEP'||chunk==='ERR_AUTO_SLEEP_STORAGE'){legacyStatus('Watch rejected the auto-sleep setting');return}if(chunk==='WEATHER_STARTED'){legacyStatus('Weather update started on the watch');return}if(chunk==='WEATHER_OK'){legacyStatus('Weather updated successfully');return}if(chunk==='WEATHER_FAILED'||chunk==='ERR_WIFI'){legacyStatus('Weather update failed; cached weather should remain on the watch');return}if(chunk==='WIFI_SCAN_STARTED'){legacyStatus('Watch is scanning Wi-Fi networks…');return}if(chunk==='WIFI_SCAN_ERROR'){legacyStatus('Wi-Fi scan failed on the watch');return}if(chunk==='GPS_OK'||chunk==='TIME_OK'||chunk==='SLEEP_OK'){legacyStatus('Watch acknowledged: '+chunk);return}state.legacyBuffer+=chunk;if(state.legacyBuffer.length>8192){state.legacyBuffer='';legacyStatus('Wi-Fi response was too large or incomplete');return}if(state.legacyBuffer.trim().endsWith(']')){try{const networks=JSON.parse(state.legacyBuffer);if(Array.isArray(networks)){const select=$('#wifiSelect');select.innerHTML='<option value="">Select a network</option>';networks.forEach(ssid=>{const op=document.createElement('option');op.value=ssid;op.textContent=ssid;select.append(op)});legacyStatus('Found '+networks.length+' Wi-Fi networks')}state.legacyBuffer=''}catch(e){state.legacyBuffer='';legacyStatus('Could not parse Wi-Fi scan response')}}}

const WFS_UUID={service:'f2c6b100-2f3a-4c1b-9d70-8e4a5c6b7100',controlRx:'f2c6b101-2f3a-4c1b-9d70-8e4a5c6b7100',controlTx:'f2c6b102-2f3a-4c1b-9d70-8e4a5c6b7100',dataRx:'f2c6b103-2f3a-4c1b-9d70-8e4a5c6b7100',dataTx:'f2c6b104-2f3a-4c1b-9d70-8e4a5c6b7100'};
function wfsCrc16(bytes){let crc=0xffff;for(let i=0;i<bytes.length;i++){crc^=bytes[i]<<8;for(let b=0;b<8;b++)crc=(crc&0x8000)?((crc<<1)^0x1021)&0xffff:(crc<<1)&0xffff}return crc}
function wfsCrc32(bytes){let crc=0xffffffff;for(let i=0;i<bytes.length;i++){crc^=bytes[i];for(let b=0;b<8;b++)crc=(crc&1)?((crc>>>1)^0xedb88320):(crc>>>1)}return (crc^0xffffffff)>>>0}
function wfsHex(bytes){return [...bytes].map(v=>v.toString(16).padStart(2,'0')).join('')}
function wfsEncodeFrame(type,payload=new Uint8Array(),sessionOverride){const w=state.wfs;if(!w)throw Error('WFS is not connected');if(payload.length>224)throw Error('WFS frame payload exceeds 224 bytes');const frame=new Uint8Array(16+payload.length),view=new DataView(frame.buffer);frame[0]=0x57;frame[1]=0x46;frame[2]=1;frame[3]=0;frame[4]=type;frame[5]=0;view.setUint16(6,w.txSequence++,true);view.setUint32(8,sessionOverride===undefined?w.sessionId:sessionOverride,true);view.setUint16(12,payload.length,true);view.setUint16(14,wfsCrc16(frame.subarray(0,14)),true);frame.set(payload,16);return frame}
function wfsDecodeFrame(data){const bytes=new Uint8Array(data.buffer,data.byteOffset,data.byteLength);if(bytes.length<16||bytes[0]!==0x57||bytes[1]!==0x46||bytes[2]!==1||bytes[3]>0||bytes[5]!==0)throw Error('Invalid WFS frame header');const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);const length=view.getUint16(12,true);if(bytes.length!==16+length||view.getUint16(14,true)!==wfsCrc16(bytes.subarray(0,14)))throw Error('WFS frame length or CRC mismatch');return {type:bytes[4],sequence:view.getUint16(6,true),sessionId:view.getUint32(8,true),payload:bytes.slice(16)}}
function waitForWfsMessage(type,timeout=8000){const w=state.wfs;if(!w)return Promise.reject(Error('WFS is not connected'));let entry;const promise=new Promise((resolve,reject)=>{entry={resolve,reject,timer:null};w.pending.set(type,entry);entry.timer=setTimeout(()=>{if(w.pending.get(type)===entry){w.pending.delete(type);reject(Error('WFS response timeout: 0x'+type.toString(16))) }},timeout)});promise.cancel=()=>{if(w.pending.get(type)===entry){w.pending.delete(type);clearTimeout(entry.timer);entry.resolve(null)}};return promise}
function handleWfsNotification(event){const w=state.wfs;if(!w)return;try{const frame=wfsDecodeFrame(event.target.value);if(w.sessionId&&frame.sessionId!==w.sessionId)throw Error('WFS session mismatch');if(frame.type===0x7f){const detail=new TextDecoder().decode(frame.payload);const error=Error('Device rejected request: '+detail);for(const entry of w.pending.values()){clearTimeout(entry.timer);entry.reject(error)}w.pending.clear();legacyStatus(error.message);return}if(frame.type===0x02)w.sessionId=frame.sessionId;const entry=w.pending.get(frame.type);if(entry){w.pending.delete(frame.type);clearTimeout(entry.timer);entry.resolve(frame)}}catch(e){legacyStatus('WFS notification error: '+e.message)}}
async function sendWfsFrame(type,payload,channel='control',sessionOverride){const w=state.wfs;if(!w)throw Error('Connect to the watch first');const bytes=payload||new Uint8Array();const maxPayload=channel==='data'?224:220;if(bytes.length>maxPayload)throw Error('WFS '+channel+' payload exceeds '+maxPayload+'-byte limit');const characteristic=channel==='data'?w.dataRx:w.controlRx;const frame=wfsEncodeFrame(type,bytes,sessionOverride);if(characteristic.writeValueWithResponse)await characteristic.writeValueWithResponse(frame);else await characteristic.writeValue(frame)}
async function sendWfsFrameAndWait(type,payload,responseType,timeout=8000,channel='control',sessionOverride){if(!state.wfs)throw Error('WFS is not connected');const pending=waitForWfsMessage(responseType,timeout);try{await sendWfsFrame(type,payload,channel,sessionOverride);const frame=await pending;if(frame===null)throw Error('WFS response waiter was cancelled');return frame}catch(error){pending.cancel?.();throw error}}
async function sendWfsJsonAndWait(type,value,responseType,timeout=8000){const payload=new TextEncoder().encode(JSON.stringify(value||{}));return sendWfsFrameAndWait(type,payload,responseType,timeout,'control')}
async function sendWfsJson(type,value){const payload=new TextEncoder().encode(JSON.stringify(value||{}));await sendWfsFrame(type,payload,'control')}
async function connectWfsProtocol(server){const service=await server.getPrimaryService(WFS_UUID.service);const controlRx=await service.getCharacteristic(WFS_UUID.controlRx);const controlTx=await service.getCharacteristic(WFS_UUID.controlTx);const dataRx=await service.getCharacteristic(WFS_UUID.dataRx);const dataTx=await service.getCharacteristic(WFS_UUID.dataTx);state.wfs={controlRx,controlTx,dataRx,dataTx,sessionId:0,txSequence:0,pending:new Map()};await controlTx.startNotifications();await dataTx.startNotifications();controlTx.addEventListener('characteristicvaluechanged',handleWfsNotification);dataTx.addEventListener('characteristicvaluechanged',handleWfsNotification);const hello=await sendWfsFrameAndWait(0x01,new TextEncoder().encode(JSON.stringify({minMajor:1,maxMajor:1,client:'WatchFaceStudio'})),0x02,8000,'control',0);const helloData=JSON.parse(new TextDecoder().decode(hello.payload));state.wfs.sessionId=hello.sessionId;if(!state.wfs.sessionId)throw Error('Device did not create a WFS session');const caps=await sendWfsFrameAndWait(0x03,new Uint8Array(),0x04,8000);state.wfsCapabilities=JSON.parse(new TextDecoder().decode(caps.payload));await refreshWfsStatus();legacyStatus('WFS v1 ready · '+helloData.device+' · package transfer '+(state.wfsCapabilities.upload?'available':'unavailable'));return state.wfsCapabilities}
async function refreshWfsStatus(){if(!state.wfs)return null;const frame=await sendWfsFrameAndWait(0x05,new Uint8Array(),0x06,8000);state.wfsStatus=JSON.parse(new TextDecoder().decode(frame.payload));const status=state.wfsStatus;if($('#deviceStatus'))$('#deviceStatus').textContent='Connected · '+(status.wifiConnected?'Wi-Fi online':'Wi-Fi offline');return status}
function designCompatibilityErrors(design,caps){
 const errors=[];
 if(!design||design.schemaVersion!==1)errors.push('Unsupported Watch Face schema version');
 const profileId=caps?.pid||'esp32-c3-gc9a01-240';
 if(design?.deviceProfileId!==profileId)errors.push('Design targets a different device profile ('+profileId+')');
 const canvas=design?.canvas||{};
 const canvasWidth=Number(caps?.cw)||240,canvasHeight=Number(caps?.ch)||240;
 const canvasShape=caps?.cs||'circle';
 const maxBitmapWidth=Number(caps?.bw)||canvasWidth,maxBitmapHeight=Number(caps?.bh)||canvasHeight;
 if(canvas.width!==canvasWidth||canvas.height!==canvasHeight)errors.push('Canvas must match the connected device resolution ('+canvasWidth+' × '+canvasHeight+')');
 if(canvas.shape&&canvas.shape!==canvasShape)errors.push('Canvas shape is not supported by the connected device');
 const maxObjects=Number(caps?.obj)||16;
 const maxAssets=Number(caps?.assets)||16;
 const objects=Array.isArray(design?.objects)?design.objects:[];
 if(objects.length>maxObjects)errors.push('This firmware supports at most '+maxObjects+' objects per face');
 const imageObjects=objects.filter(o=>o?.type==='image');
 const imageAssetIds=new Set(imageObjects.map(o=>o.assetId).filter(Boolean));
 if(imageAssetIds.size>maxAssets)errors.push('This firmware supports at most '+maxAssets+' unique image assets per face');
 const supported=new Set(['text','digital-clock','analog-clock','date','weather','shape','image']);
 for(const o of objects){
  const name=o?.name||o?.id||'Unnamed element',t=o?.transform||{},s=o?.textStyle||{},b=o?.dataBinding||{};
  if(!supported.has(o.type))errors.push(name+': element '+o.type+' is not supported by this firmware');
  if(o.type==='image'){
   if(!caps?.img)errors.push(name+': RGB565 image assets are not enabled by this firmware');
   if(!state.images.some(a=>a.id===o.assetId))errors.push(name+': source image asset is missing from this browser');
   if(t.width<1||t.height<1||t.width>maxBitmapWidth||t.height>maxBitmapHeight)errors.push(name+': image dimensions exceed the connected device bitmap limit ('+maxBitmapWidth+' × '+maxBitmapHeight+')');
  }
  if(o.type==='shape'&&!['rect','circle','rounded-rect','line'].includes(o.shape||'rect'))errors.push(name+': selected shape is not supported by this firmware');
  if(t.rotation&&Math.abs(t.rotation)>0.001)errors.push(name+': rotation is not supported yet');
  if(t.opacity!==undefined&&t.opacity<1)errors.push(name+': partial opacity is not supported yet');
  const font=s.fontFamily;
  if(font&&font!=='system-ui'&&font!=='sans-serif'&&font!=='inherit')errors.push(name+': font '+font+' is not available on the device yet');
  if(s.fontSize!==undefined&&(s.fontSize<=0||s.fontSize>256))errors.push(name+': font size is outside the device range');
  if(s.fontWeight!==undefined&&![400,600].includes(Number(s.fontWeight)))errors.push(name+': this firmware currently supports regular and semibold weights only');
  for(const axis of ['scaleX','scaleY'])if(s[axis]!==undefined&&(!Number.isFinite(Number(s[axis]))||Number(s[axis])<0.1||Number(s[axis])>8))errors.push(name+': '+axis+' must be between 0.1 and 8');
  if(s.letterSpacing!==undefined&&Number(s.letterSpacing)!==0)errors.push(name+': letter spacing is not supported yet');
  if(o.type==='digital-clock'&&b.source!=='time')errors.push(name+': digital clock requires the time binding');
  if(o.type==='date'&&b.source!=='date')errors.push(name+': date requires the date binding');
  if(o.type==='weather'&&b.source!=='temperature')errors.push(name+': only temperature weather binding is supported currently');
 }
 return [...new Set(errors)];
}
async function convertImageToRgb565(object,design){
 const source=state.images.find(a=>a.id===object.assetId);
 if(!source)throw Error(object.name+': image source not found');
 const image=new Image();image.src=source.data;
 if(image.decode)await image.decode();
 else await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Could not decode '+source.name))});
 const transform=object.transform||{};
 const x=Number(transform.x)||0,y=Number(transform.y)||0;
 const width=Number(transform.width),height=Number(transform.height);
 if(!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(width)||!Number.isFinite(height)||width<=0||height<=0)
  throw Error(object.name+': image position or size is invalid');
 // Keep only the part intersecting the 240x240 display. The LCD's circular
 // aperture is applied below, so oversized source images are never rejected.
 const left=Math.max(0,Math.floor(x)),top=Math.max(0,Math.floor(y));
 const right=Math.min(240,Math.ceil(x+width)),bottom=Math.min(240,Math.ceil(y+height));
 const outputWidth=right-left,outputHeight=bottom-top;
 if(outputWidth<=0||outputHeight<=0)throw Error(object.name+': image is outside the visible watch area');
 const imagePosition=design.objects.indexOf(object),imageZ=transform.zIndex??0;
 const hasUnderlyingLayer=design.objects.some((candidate,index)=>{
  if(candidate===object||candidate.visible===false)return false;
  const t=candidate.transform||{};
  const lowerOrder=(t.zIndex??0)<imageZ||((t.zIndex??0)===imageZ&&index<imagePosition);
  return lowerOrder&&t.x<x+width&&t.x+t.width>x&&t.y<y+height&&t.y+t.height>y;
 });
 const alphaCanvas=document.createElement('canvas');alphaCanvas.width=240;alphaCanvas.height=240;
 const alphaCtx=alphaCanvas.getContext('2d',{willReadFrequently:true});alphaCtx.drawImage(image,0,0,240,240);
 const sourcePixels=alphaCtx.getImageData(0,0,240,240).data;let hasTransparency=false;
 for(let i=3;i<sourcePixels.length;i+=4){if(sourcePixels[i]!==255){hasTransparency=true;break}}
 if(hasTransparency&&object.visible!==false&&hasUnderlyingLayer)
  throw Error(object.name+': transparent overlay images are not supported yet; place the transparent image below every other visible layer');

 const fitScale=Math.min(width/image.naturalWidth,height/image.naturalHeight);
 const drawWidth=image.naturalWidth*fitScale,drawHeight=image.naturalHeight*fitScale;
 const drawX=x+(width-drawWidth)/2,drawY=y+(height-drawHeight)/2;
 const canvas=document.createElement('canvas');canvas.width=outputWidth;canvas.height=outputHeight;
 const ctx=canvas.getContext('2d',{willReadFrequently:true});
 ctx.fillStyle=design.canvas.backgroundColor||'#000000';ctx.fillRect(0,0,outputWidth,outputHeight);
 // Clip in global watch coordinates: center (120,120), radius 120.
 ctx.save();ctx.beginPath();ctx.arc(120-left,120-top,120,0,Math.PI*2);ctx.clip();
 ctx.drawImage(image,drawX-left,drawY-top,drawWidth,drawHeight);ctx.restore();
 const rgba=ctx.getImageData(0,0,outputWidth,outputHeight).data;
 const bytes=new Uint8Array(outputWidth*outputHeight*2);
 for(let i=0,p=0;i<rgba.length;i+=4,p+=2){
  const r=rgba[i]>>3,g=rgba[i+1]>>2,b=rgba[i+2]>>3;
  const rgb565=(r<<11)|(g<<5)|b;bytes[p]=rgb565&255;bytes[p+1]=(rgb565>>8)&255;
 }
 return {x:left,y:top,width:outputWidth,height:outputHeight,bytes};
}

function advancedFeatureErrors(design){
 const errors=[];
 if(design?.canvas?.shape&&design.canvas.shape!=='circle')errors.push('This device profile only supports a circular canvas');
 for(const o of design?.objects||[]){
  const t=o.transform||{},s=o.textStyle||{},b=o.dataBinding||{},style=o.style||{},h=o.handConfig||{},rh=o.renderHints||{};
  if(t.anchor&&t.anchor!=='top-left')errors.push(o.name+': only top-left object anchoring is supported');
  if(typeof o.text==='string'&&Array.from(o.text).some(ch=>{const n=ch.codePointAt(0);return n<32||n>126}))errors.push(o.name+': this firmware currently supports printable ASCII text only');
  if(o.shape==='arc')errors.push(o.name+': arc shapes are not supported yet');
  if(o.weatherFields?.some(field=>!['temperature','condition'].includes(field)))errors.push(o.name+': this firmware supports only temperature and condition weather fields');
  if(o.glyphOverrides?.length)errors.push(o.name+': per-glyph overrides are not supported yet');
  if(o.glyphAtlasAssetId)errors.push(o.name+': custom glyph atlases are not supported by this firmware build');
  if(o.glyphFallback&&o.glyphFallback!=='compatibility-error')errors.push(o.name+': selected glyph fallback mode is not supported');
  if(['fontId','width','height'].some(k=>Object.prototype.hasOwnProperty.call(s,k)))errors.push(o.name+': custom glyph font metrics are not supported yet');
  if((s.stroke&&s.stroke!=='none')||(Number(s.strokeWidth)||0)>0||s.backgroundColor||(s.backgroundShape&&s.backgroundShape!=='none')||(Number(s.backgroundRadius)||0)>0||(Number(s.opacity??1)<0.999)||(Number(s.rotation)||0)!==0||(s.visible===false)||(Number(s.zIndex)||0)!==0)errors.push(o.name+': advanced glyph styling is not supported yet');
  if(style.backgroundColor||(Number(style.strokeWidth)!==0&&Number(style.strokeWidth)!==1&&style.strokeWidth!==undefined))errors.push(o.name+': this device supports only a one-pixel shape outline and no separate background fill');
  if(Object.values(h).some(v=>v&&typeof v==='object'&&Object.keys(v).length>0))errors.push(o.name+': custom analog hand configuration is not supported yet');
  if(b.timezone||b.fallbackText||b.visibleWhenMissing===true)errors.push(o.name+': this data-binding option is not supported by the device');
  if(b.source&& !((o.type==='digital-clock'&&b.source==='time')||(o.type==='date'&&b.source==='date')||(o.type==='weather'&&b.source==='temperature')))errors.push(o.name+': this data binding is not supported by the device');
  if(b.format&&o.type==='digital-clock'&&/[A-Za-z]/.test(b.format.replace(/HH|mm|ss/g,'')))errors.push(o.name+': time format contains unsupported tokens');
  if(b.format&&o.type==='date'&&/[A-Za-z]/.test(b.format.replace(/YYYY|ddd|MMM|MM|DD/g,'')))errors.push(o.name+': date format contains unsupported tokens');
  if(typeof b.format==='string'&&Array.from(b.format).some(ch=>ch.codePointAt(0)>126))errors.push(o.name+': date/time format must use printable ASCII characters');
  if(rh.requiresAntialias===true||rh.requiresBitmap===true)errors.push(o.name+': requested render hint is not supported by the device');
  if(o.clockMode&&((o.type==='analog-clock'&&o.clockMode!=='analog')||(o.type==='digital-clock'&&o.clockMode!=='digital')||!['analog-clock','digital-clock'].includes(o.type)))errors.push(o.name+': clock mode does not match the selected clock element');
  if(o.showAmPm===false&&o.timeFormat==='12h')errors.push(o.name+': hiding AM/PM in 12-hour mode is not supported yet');
 }
 return errors;
}

